    def test_named_coupled_fence_fixtures(self):
        import coupled_tests
        files = {'src/x.py': '# source\n', 'src/test_x.py': '# named\n'}
        root, repo, base, tree, events = self.scratch_case('', files=files)
        for token, fenced in (('`src/test_x.py`: unchanged.', True),
                              ('- src/test_x.py, unchanged.', True),
                              ('test_x.py', False), ('old/src/test_x.py', False),
                              ('src/test_x.py.orig', False), ('other/test_x.py', False),
                              ('No fence.\n## Other\nsrc/test_x.py', False)):
            text = self.input_text('', writes='src/x.py') + '\n## Boundaries\n' + token + '\n'
            self.assertEqual(coupled_tests.scan(text, repo, base),
                             [('named', 'src/x.py', 'src/test_x.py', fenced)], token)
            (root / 'content' / (self.sid + '.md')).write_text(text)
            with patch.object(readiness.grading_env, '_project_row', return_value={}):
                result = readiness.check(self.sid, 'do-it-v2', base, events, root=root, dry_run=False)
            self.assertEqual(result['findings'], [] if fenced else [
                'Writes omits coupled tests/companions: src/test_x.py'], token)
            self.assertEqual(result['status'], 'ready' if fenced else 'bounced', token)
            print(json.dumps(dict(case='AC4/' + token, scan=coupled_tests.scan(text, repo, base),
                                  status=result['status'], findings=result['findings'])))
            self.assertFalse(readiness.merge_gate.granted('src/test_x.py',
                             readiness.merge_gate.grant_from_text(text)))
        for sid, source, test in (('L-spec-2134', 'src/fold.py', 'src/test_fold_stalls.py'),
                                  ('L-spec-2159', 'src/dispatch.py', 'src/test_dispatch_cwd.py')):
            boundary = coupled_tests.boundaries(FIXTURES[sid]['text'])
            self.assertIn(test, boundary)
            text = self.input_text('', writes=source) + '\n## Boundaries\n' + boundary
            case = self.scratch_case(text, files={source: '# source\n', test: '# named\n'})
            root, repo, base, tree, events = case
            self.assertEqual(coupled_tests.scan(text, repo, base), [('named', source, test, True)], sid)
            self.assertEqual(readiness.companion_gaps(text, [source], repo, base, tree), [], sid)
            unfenced = text.replace(boundary, boundary.replace(test, 'omitted'))
            self.assertEqual(readiness.companion_gaps(unfenced, [source], repo, base, tree), [test], sid)
            for token, expected in ((boundary, True), ('', False),
                                    (Path(test).name, False), ('old/' + test, False),
                                    (test + '.orig', False), ('other/' + test, False),
                                    ('No fence.\n## Other\n' + test, False)):
                candidate = self.input_text('', writes=source) + '\n## Boundaries\n' + token
                (root / 'content' / (self.sid + '.md')).write_text(candidate)
                rows = coupled_tests.scan(candidate, repo, base)
                result = readiness.check(self.sid, 'do-it-v2', base, events, root=root, dry_run=False)
                findings = [] if expected else ['Writes omits coupled tests/companions: ' + test]
                self.assertEqual(rows, [('named', source, test, expected)], (sid, token))
                self.assertEqual((result['status'], result['findings']),
                                 ('ready' if expected else 'bounced', findings), (sid, token))
                self.assertFalse(readiness.merge_gate.granted(test,
                                 readiness.merge_gate.grant_from_text(candidate)))
                print(json.dumps(dict(case=sid + '/' + token, scan=rows,
                                      status=result['status'], findings=result['findings'])))
        self.assert_case('L-spec-2154/no-fence', FIXTURES['L-spec-2154']['text'], files={
            'src/tick.py': 'def run_steps(): pass\n',
            'src/test_tick.py': '# named test is granted\n',
            'src/nextstep.py': 'def next_steps(): pass\nclass Step: pass\n',
            'src/autodispatch.py': 'def _grader_trigger(): pass\n',
            'src/grader_packet.py': 'def _same_sha(): pass\n',
            'src/evidence_revision.py': 'def current(): pass\n',
            'src/attempts.py': 'def history(): pass\nBACKOFF_MIN = 1\nMAX_ATTEMPTS = 2\n',
        })
        text = self.input_text('', writes='src/howto.py') + (
            '\n## Boundaries\n- new event; `src/test_howto.py` unchanged.\n')
        root, repo, base, tree, events = self.scratch_case(text, files={
            'src/howto.py': '# source\n', 'src/test_howto.py': '# named and mandatory\n'})
        self.assertEqual(readiness.companion_gaps(text, ['src/howto.py'], repo, base, tree),
                         ['src/test_howto.py'])
        result = readiness.check(self.sid, 'do-it-v2', base, events, root=root, dry_run=False)
        self.assertEqual((result['status'], result['findings']), ('bounced', [
            'Writes omits coupled tests/companions: src/test_howto.py']))
        print(json.dumps(dict(case='AC4/mandatory', status=result['status'], findings=result['findings'])))

    def test_fail_closed_input_matrix(self):
        # No producer, one eligible producer, ambiguity and lifecycle/project rejection.
        for kind, consumes, production, writes, finding in (
                ('path', '- `src/required.py`', '- required file', 'src/required.py', 'src/required.py'),
                ('symbol', '- `source.future()`', '- `source.future()`', 'source.py', 'source.future')):
            self.spec(consumes)
            producer_events = []
            for sid in ('L-spec-9001', 'L-spec-9002'):
                path = self.root / 'content' / (sid + '.md')
                path.write_text('Produces:\n' + production + '\nWrites: ' + writes + '\n')
                producer_events.append(dict(type='spec-written', subject=sid, project='demo', path=str(path)))
            for label, extra, status in (
                    ('zero', [], 'bounced'), ('unique', producer_events[:1], 'held'),
                    ('multiple', producer_events, 'bounced'),
                    ('shipped', producer_events[:1] + [dict(type='shipped', subject='L-spec-9001')], 'bounced'),
                    ('killed', producer_events[:1] + [dict(type='spec-killed', subject='L-spec-9001')], 'bounced'),
                    ('wrong-project', [dict(producer_events[0], project='other')], 'bounced')):
                result = readiness.check(self.sid, 'demo', self.base, self.events + extra,
                                         root=self.root, dry_run=False)
                self.assertEqual((result['status'], result['waits_for'], result['findings']),
                                 (status, 'L-spec-9001' if status == 'held' else None,
                                  ['missing ' + kind + ': ' + finding] if status == 'held' else [
                                      'missing inputs without a unique producer: ' + finding]), (kind, label))
                print(json.dumps(dict(case='AC5/' + kind + '/' + label, result=result)))

        # classify_selected is a consumer seam, absent until committed at the dispatch base.
        for sid in ('L-spec-2144', 'L-spec-2149'):
            text = self.input_text('- `base_red.classify_selected(project, sha, ids)`')
            case = self.assert_case(sid + '/dependency', text, files={
                'src/base_red.py': 'def rerun_on_base(): pass\n'},
                missing=[('symbol', 'base_red.classify_selected')])
            root, repo, base, tree, events, _ = case
            (repo / 'src/base_red.py').write_text('def classify_selected(): pass\n')
            result = readiness.check(self.sid, 'do-it-v2', base, events, root=root, dry_run=False)
            self.assertEqual(result['status'], 'bounced', sid + '/uncommitted')
            subprocess.check_call(['git', '-C', str(repo), 'commit', '-qam', 'land prerequisite'])
            committed = subprocess.check_output(['git', '-C', str(repo), 'rev-parse', 'HEAD'], text=True).strip()
            result = readiness.check(self.sid, 'do-it-v2', committed, events, root=root, dry_run=False)
            self.assertEqual((result['status'], result['findings']), ('ready', []), sid + '/committed')

        self.spec('- `def existing()` from `source.py`')
        original_run = subprocess.run
        def lookup_failure(*args, **kwargs):
            if 'grep' in args[0]:
                return SimpleNamespace(returncode=2)
            return original_run(*args, **kwargs)
        injections = (
            ('tree', patch.object(readiness, 'git', side_effect=readiness.NotReady('tree unavailable'))),
            ('git-timeout', patch.object(readiness, 'git', side_effect=subprocess.TimeoutExpired('git', 30))),
            ('symbol', patch.object(readiness.subprocess, 'run', side_effect=lookup_failure)),
            ('truncated', patch.object(readiness.coupled_tests, 'reference_matches',
                                       side_effect=readiness.coupled_tests.Truncated)),
            ('scan-timeout', patch.object(readiness.coupled_tests, 'reference_matches',
                                          side_effect=subprocess.TimeoutExpired('scan', 30))),
        )
        for label, injection in injections:
            with injection:
                result = self.check(dry_run=False)
            self.assertEqual(result['status'], 'bounced', label)
            self.assertTrue(result['findings'], label)
            print(json.dumps(dict(case='AC5/' + label, result=result)))
        for base in ('invalid', '0' * 40):
            result = readiness.check(self.sid, 'demo', base, self.events, root=self.root, dry_run=False)
            self.assertEqual(result['status'], 'bounced', base)
        for label, text in (
                ('invalid-grant', self.input_text('', writes='see the table below')),
                ('unknown-owner', self.input_text('- `src/absent.py` in project unknown-project')),
                ('unresolved-source', self.input_text('- Q/unknown.call', context='Q: `src/other.py`'))):
            (self.root / 'content' / (self.sid + '.md')).write_text(text)
            result = self.check(dry_run=False)
            self.assertEqual(result['status'], 'bounced', label)
            print(json.dumps(dict(case='AC5/' + label, result=result)))
        self.spec('- `local/missing.py`')
        result = readiness.check(self.sid, 'demo', self.base,
                                 self.events + [dict(type='build-done', subject=self.sid)], root=self.root)
        self.assertEqual(result['status'], 'already-built')
        # These existing tests exercise real verification commands and timeout/checkout injection.
        self.test_broken_environment_still_bounces()
        self.test_base_timeout_and_checkout_or_dependency_failures_still_block()

    def test_readiness_persists_to_fresh_ledger_reader(self):
        files = {'src/service.py': '# source\n', 'src/test_reader.py': 'import src.service\n'}
        for label, line, status in (('ready', '', 'ready'),
                                    ('held', '- `service.future()`', 'held'),
                                    ('bounced', '- `service.absent()`', 'bounced')):
            text = self.input_text(line, writes='src/service.py')
            root, repo, base, tree, events = self.scratch_case(text, files=files)
            producer = root / 'content/L-spec-9001.md'
            producer.write_text('Produces:\n- `service.future()`\nWrites: src/service.py\n')
            events.append(dict(type='spec-written', subject='L-spec-9001', project='do-it-v2', path=str(producer)))
            result = readiness.check(self.sid, 'do-it-v2', base, events, root=root, dry_run=False)
            self.assertEqual(result['status'], status)
            readiness.record(result, 'do-it-v2', root=root)
            # emit has closed its file before a separate interpreter imports the uncached reader.
            env = dict(os.environ, DOIT_ROOT=str(root), DOIT_PROJECT='do-it-v2',
                       PYTHONPATH=str(Path(readiness.__file__).resolve().parent))
            readback = subprocess.check_output([sys.executable, '-B', '-c',
                'import json, fold; print(json.dumps(fold.read_events(use_cache=False)))'], env=env, text=True)
            rows = json.loads(readback)
            expected_types = ['build-readiness'] + ({'held': ['dependency-hold'],
                                                    'bounced': ['spec-shape-failed']}.get(status, []))
            self.assertEqual([row['type'] for row in rows], expected_types)
            row = rows[0]
            for key in ('base_sha', 'status', 'findings', 'waits_for', 'run_tests'):
                self.assertEqual(row[key], result[key], (label, key))
            self.assertEqual((row['subject'], row['project']), (self.sid, 'do-it-v2'))
            if status == 'ready':
                self.assertEqual(row['run_tests'], ['src/test_reader.py'])
            for companion in rows[1:]:
                self.assertEqual((companion['subject'], companion['project']), (self.sid, 'do-it-v2'))
                if status == 'held':
                    self.assertEqual(companion['waits_for'], result['waits_for'])
                else:
                    self.assertEqual(companion['findings'], result['findings'])
            print(json.dumps(dict(case='AC6/' + label, persisted=rows)))

